import * as T from '../vendor/three.module.js';
import {GEM_PROFILES} from './character.10836e306be6.js';
// Character implementation owns geometry, appearance and animation only.
export class ClassicCharacter {
 constructor({createCanvas=()=>document.createElement('canvas')}={}){this.createCanvas=createCanvas;this.root=new T.Group();this.head=new T.Group();this.root.add(this.head);this.head.position.y=1.72;this.mood='idle';this.accent=new T.MeshStandardMaterial({color:0xef6b79,roughness:.55});this.shell=new T.MeshStandardMaterial({color:0x343d4c,roughness:.48});this.dark=new T.MeshStandardMaterial({color:0x080d17,roughness:.25});this.white=new T.MeshStandardMaterial({color:0xabb7c2,roughness:.55});this.faceTex=this.makeFace();this.build();}
 rounded(w,h,d,r,material){const s=new T.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);const g=new T.ExtrudeGeometry(s,{depth:d-2*r,bevelEnabled:true,bevelSegments:4,steps:1,bevelSize:r,bevelThickness:r,curveSegments:10});g.center();const m=new T.Mesh(g,material);m.castShadow=true;m.receiveShadow=true;return m;}
 add(parent,w,h,d,r,mat,pos){const m=this.rounded(w,h,d,r,mat);m.position.set(...pos);parent.add(m);return m;}
 build(){this.add(this.head,1.65,1.27,.95,.13,this.shell,[0,0,0]);this.add(this.head,1.45,1.05,.13,.08,this.accent,[0,0,.48]);this.add(this.head,1.35,.95,.12,.075,this.dark,[0,0,.55]);const face=new T.Mesh(new T.PlaneGeometry(1.28,.86),new T.MeshBasicMaterial({map:this.faceTex}));face.position.set(0,0,.625);this.head.add(face);
 for(const side of [-1,1]){this.add(this.head,.15,.72,.64,.06,this.accent,[side*.94,.04,-.03]);this.add(this.head,.09,.47,.4,.035,this.dark,[side*1.065,.04,-.03]);}this.add(this.head,1.5,.13,.6,.05,this.accent,[0,.76,-.04]);this.add(this.root,.68,.38,.55,.07,this.shell,[0,.82,-.04]);this.feet=[];for(const side of [-1,1]){const pivot=new T.Group();pivot.position.set(side*.43,.43,0);this.root.add(pivot);this.add(pivot,.25,.42,.3,.04,this.white,[0,.0,0]);this.add(pivot,.59,.25,.83,.08,this.shell,[0,-.25,.14]);this.add(pivot,.57,.055,.77,.02,this.accent,[0,-.39,.14]);this.feet.push(pivot);}for(let i=0;i<4;i++)this.add(this.head,.5,.025,.025,.006,this.dark,[0,-.18+i*.1,-.49]);}
 makeFace(){this.canvas=this.createCanvas();this.canvas.width=512;this.canvas.height=340;this.ctx=this.canvas.getContext('2d');return new T.CanvasTexture(this.canvas);}
 setAccent(color){this.accent.color.set(color);this.eyeColor=color;}
 setProfile(id){this.profile=GEM_PROFILES.find(p=>p.id===id)||GEM_PROFILES[0];this.setAccent(this.profile.color);}
 setMood(mood){this.mood=mood;}
 update(t,{pointer={x:0,y:0},follow=true,dance=false}={}){this.head.position.y=1.72+Math.sin(t*2)*.025;this.head.rotation.z=dance?Math.sin(t*7)*.18:Math.sin(t)*.025;this.head.rotation.y=follow?pointer.x*.18:0;this.head.rotation.x=follow?-pointer.y*.08:0;this.feet.forEach((f,i)=>{f.rotation.x=dance?Math.sin(t*7+i*Math.PI)*.35:0;});const c=this.ctx;c.fillStyle='#080d17';c.fillRect(0,0,512,340);c.fillStyle=this.eyeColor||'#83f4ed';c.shadowColor=this.eyeColor||'#50ddd6';c.shadowBlur=18;const blink=Math.sin(t*1.3)> .993;const gazeX=follow?pointer.x*25:0,gazeY=follow?-pointer.y*18:0;for(const base of [170,342]){const x=base+gazeX;c.beginPath();if(this.mood==='happy'){c.lineWidth=21;c.strokeStyle=this.eyeColor||'#83f4ed';c.arc(x,185+gazeY,51,Math.PI,Math.PI*2);c.stroke();}else{const h=blink?7:this.mood==='sleep'?13:this.mood==='listen'?156:142;c.roundRect(x-50,161+gazeY-h/2,100,h,Math.min(31,h/2));c.fill();}}c.shadowBlur=0;if(this.mood==='listen'){c.fillStyle='#ef6b79';c.beginPath();c.arc(256,275,6+Math.sin(t*4)*2,0,Math.PI*2);c.fill();}this.faceTex.needsUpdate=true;}
}
